
.chars {
  background: var(--c-paper);
  border-bottom: 1px solid var(--c-line);
  display: flex;
  flex-direction: column;
}

.char {
  padding: 10px 14px;

  & + .char {
    border-top: 1px dashed var(--c-line);
  }
}

.icon {
  width: 15px;
  height: 15px;
  flex: none;
  color: var(--c-coral);
}

.char-main {
  display: flex;
  align-items: center;
  gap: 8px;
}

.char-name {
  font-weight: 600;
  white-space: nowrap;
}

.track {
  flex: 1;
  height: 8px;
  border-radius: 99px;
  background: var(--c-coral-soft);
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 99px;
  background: var(--c-coral);
  transition: width 0.3s ease;
}

.char-value {
  min-width: 2.5em;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.char-mood {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 1px 9px;
  border-radius: 99px;
  border: 1px solid var(--c-line);
  background: var(--c-cream);
  font-size: 12px;
  white-space: nowrap;

  .dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--c-cocoa-soft);
  }

  &.is-开心 .dot {
    background: var(--c-coral);
  }

  &.is-想念 .dot {
    background: #8fa7c9;
  }

  &.is-低落 .dot {
    background: #b3a4be;
  }

  &.is-烦躁 .dot {
    background: #d96a6a;
  }
}

.char-thought {
  margin-top: 6px;
  padding-left: 23px;
  color: var(--c-cocoa-soft);
  font-size: 12px;
  overflow-wrap: anywhere;
}

.chars-empty {
  padding: 14px;
  text-align: center;
  color: var(--c-cocoa-soft);
}
