
.panel {
  background: var(--c-paper);
  border: 1px solid var(--c-line);
  border-radius: 10px;
  padding: 10px;
  min-width: 0;
}

.icon {
  width: 15px;
  height: 15px;
  flex: none;
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  color: var(--c-cocoa);

  h2 {
    font-size: 13px;
    font-weight: 600;
  }

  .count {
    margin-left: auto;
    font-size: 11px;
    color: var(--c-cocoa-soft);
    background: var(--c-cream);
    border: 1px solid var(--c-line);
    border-radius: 99px;
    padding: 0 8px;
    line-height: 18px;
  }
}

.item-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  border: 1px solid var(--c-line);
  border-radius: 8px;
  background: var(--c-cream);
}

.item-date {
  font-size: 11px;
  color: var(--c-cocoa-soft);
}

.item-text {
  overflow-wrap: anywhere;
}

.empty {
  color: var(--c-cocoa-soft);
  font-size: 12px;
  padding: 4px 2px;
}
