
.status-card {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-cream);
  border: 1px solid var(--c-line);
  border-radius: 12px;
  overflow: hidden;
  font-family: var(--font-main);
  font-size: 13px;
  line-height: 1.5;
  color: var(--c-cocoa);
  box-shadow: 0 2px 10px rgba(90, 74, 66, 0.08);
}

.who {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--c-paper);
  border-bottom: 1px solid var(--c-line);
  flex-wrap: wrap;
}

.who-pov {
  font-size: 13px;
  font-weight: 600;
  padding: 1px 10px;
  border-radius: 99px;
  border: 1px solid var(--c-line);
  background: var(--c-cream);
}

.who-date {
  margin-left: auto;
  color: var(--c-cocoa-soft);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.panel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 10px;
}

.status-empty {
  padding: 18px 12px;
  text-align: center;
  color: var(--c-cocoa-soft);
}

@media (max-width: 600px) {
  .panel-grid {
    grid-template-columns: 1fr;
  }
}
